UPDATE g_user
USER_NAME = #{userName}, PASSWORD = #{password}, NAME = #{name}, USER_STATUS = #{userStatus}, ROLE = #{role}, LOGIN_FAIL_COUNT = #{loginFailCount}, LOCK_TIME = #{lockTime},
WHERE USER_ID = #{userId}

mapper.select:
SELECT u.*, s1.CODE_DESC as USER_STATUS_DESC, s2.CODE_DESC as ROLE_DESC FROM g_user u LEFT JOIN g_code s1 ON u.USER_STATUS = s1.CODE_ID LEFT JOIN g_code s2 ON u.ROLE = s2.CODE_ID
AND u.ROLE = #{role}
AND u.USER_STATUS = #{userStatus}
AND u.NAME LIKE CONCAT('%', #{name}, '%')
AND u.ROLE != 14981003
ORDER BY u.USER_NAME

